var n=`0788-gateau-piment`;var t=`world-0788`;var a=`MU`;var s=`eastern-africa`;var o=8;var r=218;var l={en:`Gateau Piment`,ua:`Гато піма`};var d={en:`Gateau Piment is a Mauritius classic prepared with yellow split peas, yellow onion, scotch bonnet pepper, cilantro. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Гато піма, страва кухні країни Маврикій зі складниками: жовтий колотий горох, жовта цибуля, перець скотч-боннет, кінза. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Soak the dried beans or peas in plentiful cold water for 180 minutes, then drain and discard the soaking liquid; keep refrigerated in hot conditions.`,ua:`Замочіть сухі бобові у великій кількості холодної води на 180 хвилин, після чого злийте й вилийте воду від замочування; за спеки тримайте в холодильнику.`,t:[`soaking-legumes`],m:180,i:[[`yellow-split-peas`,340,`g`],[`water`,700,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:13,i:[[`yellow-onion`,170,`g`],[`scotch-bonnet-pepper`,1,`pcs`],[`ground-cumin`,5,`g`],[`cilantro`,24,`g`],[`table-salt`,5,`g`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 22 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 22 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:22,i:[[`sunflower-oil`,740,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lemon`,1,`pcs`]]}];var g={slug:n,id:t,country:`MU`,region:s,servings:8,minutes:218,title:l,text:d,steps:u};export{a as country,g as default,t as id,r as minutes,s as region,o as servings,n as slug,u as steps,d as text,l as title};